// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
        // the test contract is the deployer; initialize so it becomes owner
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        // call as the owner (this contract deployed and initialized c)
        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: after any (successful) update, the stored round
        // implementation is never the zero address.
        assertTrue(!ok || c.roundImplementation() != address(0));
    }
}
